const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const output = [];
for (const item of $input.all()) {
  const rows = Array.isArray(item.json) ? item.json : [item.json];
  for (const row of rows) {
    const key = [row.campaign_number, row.make, row.model, row.model_year].filter(Boolean).join('|');
    if (key && !store.seen[key]) {
      store.seen[key] = Date.now();
      output.push({ json: row });
    }
  }
}
const newest = Object.entries(store.seen).sort((a, b) => b[1] - a[1]).slice(0, 2000);
store.seen = Object.fromEntries(newest);
return output;
